package org.biopulse.service;
import org.biopulse.dao.RegistryDao;import org.biopulse.domain.*;import org.biopulse.dto.Requests.*;import org.biopulse.security.AccessPolicy;import org.biopulse.exception.ApiException;import org.biopulse.websocket.*;import org.springframework.stereotype.Service;import org.springframework.transaction.annotation.Transactional;
@Service public class DeviceService {
 private final RegistryDao dao;private final AccessPolicy access;private final MonitoringEventPublisher events;public DeviceService(RegistryDao dao,AccessPolicy access,MonitoringEventPublisher events){this.dao=dao;this.access=access;this.events=events;}
 @Transactional public MedicalDevice create(DeviceCreate r){MedicalDevice d=dao.createDevice(r);access.audit("REGISTER_DEVICE","device:"+d.id());return d;}
 @Transactional public DeviceAssignment assign(AssignmentCreate r){var a=dao.admission(r.admissionId()).orElseThrow(()->ApiException.missing("Admission"));if(a.status()!=AdmissionStatus.ACTIVE)throw ApiException.bad("Admission is not active");var x=dao.assign(r);access.audit("ASSIGN_DEVICE","device:"+r.deviceId());events.publish(MonitoringEvent.of("DEVICE_STATUS",r.admissionId(),null,null,null,null,null,x));return x;}
}